using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// ── Configuration ───────────────────────────────────────────────────────────
var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey    = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

// ── Tools ───────────────────────────────────────────────────────────────────
var notebook = new Notebook();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) =>
            WebSearch.SearchAsync(query),
        "web_search",
        "Search the web for information on a topic. Returns relevant snippets."),

    AIFunctionFactory.Create(
        ([Description("URL to fetch and read")] string url) =>
            WebSearch.FetchPageAsync(url),
        "fetch_page",
        "Fetch a web page and return its text content."),

    AIFunctionFactory.Create(
        ([Description("Title or heading for the note")] string title,
         [Description("Content of the note")]           string content) =>
            notebook.AddNote(title, content),
        "add_note",
        "Save a research note. Use this to record important findings."),

    AIFunctionFactory.Create(
        () => notebook.GetNotes(),
        "get_notes",
        "Retrieve all saved research notes."),

    AIFunctionFactory.Create(
        ([Description("Exact title of the note to remove")] string title) =>
            notebook.RemoveNote(title),
        "remove_note",
        "Remove a previously saved note by title."),
};

// ── Chat client with automatic tool invocation ──────────────────────────────
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(modelName)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

var systemPrompt = """
    You are a research agent. Your job is to research a topic the user gives you
    by searching the web, reading pages, and collecting notes.

    Workflow:
    1. Break the topic into sub-questions.
    2. Use `web_search` to find relevant sources for each sub-question.
    3. Use `fetch_page` to read promising results in detail.
    4. Use `add_note` to record key findings with clear titles.
    5. After thorough research, use `get_notes` to review everything you collected.
    6. Provide a well-structured summary with references.

    Be thorough but concise. Cite your sources.
    """;

var history = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt)
};

// ── Interactive loop ────────────────────────────────────────────────────────
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        🔍  Research Agent  🔍           ║");
Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("You > ");
    Console.ResetColor();

    var input = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(input)) continue;
    if (input.Equals("quit", StringComparison.OrdinalIgnoreCase)) break;

    history.Add(new(ChatRole.User, input));

    Console.ForegroundColor = ConsoleColor.Yellow;
    Console.Write("\nAgent > ");
    Console.ResetColor();

    try
    {
        var response = await client.GetResponseAsync(history, chatOptions);

        // Append all response messages to history
        foreach (var msg in response.Messages)
            history.Add(msg);

        // Print only the final assistant text
        var finalText = response.Messages
            .Where(m => m.Role == ChatRole.Assistant && m.Text is not null)
            .Select(m => m.Text)
            .LastOrDefault() ?? "(no response)";

        Console.WriteLine(finalText);
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    Console.WriteLine();
}

Console.WriteLine("Goodbye!");

