/// <summary>Provides web search and page-fetching capabilities.</summary>
static partial class WebSearch
{
    private static readonly HttpClient Http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" }
        }
    };

    /// <summary>
    /// Searches the web via DuckDuckGo Lite (no API key required) and returns
    /// a list of result snippets with URLs.
    /// </summary>
    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            var form = new FormUrlEncodedContent([new("q", query)]);
            var response = await Http.PostAsync("https://lite.duckduckgo.com/lite/", form);
            var html = await response.Content.ReadAsStringAsync();

            var results = ParseSearchResults(html);
            if (results.Count == 0)
                return "No results found.";

            var sb = new StringBuilder();
            foreach (var (title, url, snippet) in results.Take(8))
            {
                sb.AppendLine($"**{title}**");
                sb.AppendLine($"  URL: {url}");
                sb.AppendLine($"  {snippet}");
                sb.AppendLine();
            }
            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    /// <summary>Fetches a URL and returns its text content (truncated to ~6000 chars).</summary>
    public static async Task<string> FetchPageAsync(string url)
    {
        try
        {
            var html = await Http.GetStringAsync(url);
            var text = StripHtml(html);
            return text.Length > 6000 ? text[..6000] + "\n\n[...truncated]" : text;
        }
        catch (Exception ex)
        {
            return $"Failed to fetch page: {ex.Message}";
        }
    }

    private static List<(string Title, string Url, string Snippet)> ParseSearchResults(string html)
    {
        var results = new List<(string, string, string)>();

        // DuckDuckGo Lite returns results in <a> tags inside table rows
        var linkPattern = LinkRegex();
        var matches = linkPattern.Matches(html);

        string? lastUrl = null;
        string? lastTitle = null;

        foreach (Match m in matches)
        {
            var href = WebUtility.HtmlDecode(m.Groups[1].Value);
            var text = StripHtml(m.Groups[2].Value).Trim();

            if (!href.StartsWith("http")) continue;
            // Skip DuckDuckGo internal links
            if (href.Contains("duckduckgo.com")) continue;

            lastUrl = href;
            lastTitle = text;
        }

        // Broader parsing: extract all external links with surrounding text
        var snippetPattern = SnippetRegex();
        var cells = snippetPattern.Matches(html);

        var urlsFound = new HashSet<string>();
        string pendingTitle = "";
        string pendingUrl = "";

        foreach (Match cell in cells)
        {
            var content = cell.Groups[1].Value;
            var linkMatch = LinkRegex().Match(content);
            if (linkMatch.Success)
            {
                var href = WebUtility.HtmlDecode(linkMatch.Groups[1].Value);
                var text = StripHtml(linkMatch.Groups[2].Value).Trim();
                if (href.StartsWith("http") && !href.Contains("duckduckgo.com"))
                {
                    pendingTitle = text;
                    pendingUrl = href;
                }
            }
            else
            {
                var snippet = StripHtml(content).Trim();
                if (!string.IsNullOrWhiteSpace(pendingUrl) && snippet.Length > 20
                    && !urlsFound.Contains(pendingUrl))
                {
                    results.Add((pendingTitle, pendingUrl, snippet));
                    urlsFound.Add(pendingUrl);
                    pendingUrl = "";
                }
            }
        }

        // Fallback: if structured parsing found nothing, grab raw links
        if (results.Count == 0)
        {
            foreach (Match m in matches)
            {
                var href = WebUtility.HtmlDecode(m.Groups[1].Value);
                var text = StripHtml(m.Groups[2].Value).Trim();
                if (href.StartsWith("http") && !href.Contains("duckduckgo.com")
                    && !urlsFound.Contains(href) && text.Length > 3)
                {
                    results.Add((text, href, ""));
                    urlsFound.Add(href);
                }
            }
        }

        return results;
    }

    private static string StripHtml(string html)
    {
        var text = TagRegex().Replace(html, " ");
        text = WebUtility.HtmlDecode(text);
        text = WhitespaceRegex().Replace(text, " ");
        return text.Trim();
    }

    [GeneratedRegex("""<a[^>]+href=["']([^"']+)["'][^>]*>(.*?)</a>""", RegexOptions.IgnoreCase | RegexOptions.Singleline)]
    private static partial Regex LinkRegex();

    [GeneratedRegex("""<td[^>]*>(.*?)</td>""", RegexOptions.IgnoreCase | RegexOptions.Singleline)]
    private static partial Regex SnippetRegex();

    [GeneratedRegex("<[^>]+>")]
    private static partial Regex TagRegex();

    [GeneratedRegex(@"\s+")]
    private static partial Regex WhitespaceRegex();
}

/// <summary>Simple in-memory notebook for collecting research findings.</summary>
class Notebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    public string AddNote(string title, string content)
    {
        _notes.Add((title, content));
        return $"✅ Note saved: \"{title}\" ({_notes.Count} total notes)";
    }

    public string GetNotes()
    {
        if (_notes.Count == 0) return "📋 No notes yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"📋 Research Notes ({_notes.Count}):");
        sb.AppendLine(new string('─', 50));
        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"\n## {i + 1}. {_notes[i].Title}");
            sb.AppendLine(_notes[i].Content);
        }
        return sb.ToString();
    }

    public string RemoveNote(string title)
    {
        var removed = _notes.RemoveAll(n =>
            n.Title.Equals(title, StringComparison.OrdinalIgnoreCase));
        return removed > 0
            ? $"🗑️ Removed note: \"{title}\""
            : $"⚠️ Note \"{title}\" not found.";
    }
}

