IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(modelName)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

var systemPrompt = """
    You are a research agent. Your job is to research a topic the user gives you
    by searching the web, reading pages, and collecting notes.

    Workflow:
    1. Break the topic into sub-questions.
    2. Use `web_search` to find relevant sources for each sub-question.
    3. Use `fetch_page` to read promising results in detail.
    4. Use `add_note` to record key findings with clear titles.
    5. After thorough research, use `get_notes` to review everything you collected.
    6. Provide a well-structured summary with references.

    Be thorough but concise. Cite your sources.
    """;

var history = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt)
};

// ── Interactive loop ────────────────────────────────────────────────────────
